#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# All customization is below the template's STAGES marker.
set +x
umask 077
[[ -t 0 ]] || { printf 'Run this wizard in an interactive terminal.\n' >&2; exit 1; }
SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
PROJECT_DIR=$(cd -- "$SCRIPT_DIR/.." && pwd)
cd -- "$PROJECT_DIR"
ENV_FILE="$PROJECT_DIR/.env.local"
DEPLOY_ENV_FILE="$PROJECT_DIR/.env.vercel.local"
AUTH_PREPARED=false
VERCEL_READY=false
DEPLOY_KEYS=""

die() { warn "$1"; exit 1; }

# Accept simple surrounding dotenv quotes without ever sourcing an env file.
unquote() {
  local value="$1"
  case "$value" in
    \"*\") value=${value#\"}; value=${value%\"} ;;
    \'*\') value=${value#\'}; value=${value%\'} ;;
  esac
  printf '%s' "$value"
}

protect_env_file() {
  local path="$1" relative="${1##*/}"
  [[ ! -L "$path" ]] || die "$relative is a symlink; use a regular local env file."
  [[ ! -e "$path" || -f "$path" ]] || die "$relative must be a regular file."
  git check-ignore -q --no-index -- "$relative" || die "$relative must be gitignored before saving secrets."
  if git ls-files --error-unmatch -- "$relative" >/dev/null 2>&1; then
    die "$relative is tracked by Git. Remove it from tracking and rotate any exposed credentials first."
  fi
  if [[ -f "$path" ]]; then chmod 600 "$path"; fi
}

capture_connection() {
  local key="$1" kind="$2" candidate
  while :; do
    ask_secret "$key" "Paste the $kind connection URL only (input hidden):"
    candidate=$(unquote "${!key}")
    if printf '%s' "$candidate" | bun -e '
      const raw = await Bun.stdin.text();
      try {
        const u = new URL(raw);
        const kind = process.argv[1];
        const unsafe = /[\s\x00-\x1f\x7f\x22\x27\x24\x5c]/.test(raw);
        const pooled = u.hostname.includes("-pooler.");
        const valid = !unsafe && !u.hash && ["postgres:", "postgresql:"].includes(u.protocol)
          && u.hostname.endsWith(".neon.tech") && u.username && u.password && u.pathname.length > 1
          && ["require", "verify-full"].includes(u.searchParams.get("sslmode"))
          && (kind === "pooled" ? pooled : !pooled);
        process.exit(valid ? 0 : 1);
      } catch { process.exit(1); }
    ' "$kind"; then
      printf -v "$key" '%s' "$candidate"
      write_env "$key" "$candidate"
      return
    fi
    warn "Expected a complete $kind Neon PostgreSQL URL with credentials and sslmode=require."
    note "Copy the URL, not a psql command or KEY=value. Encode custom password special characters in the URL."
    confirm "Try entering this URL again?" || die "Stopped. Previously saved values are retained."
  done
}

check_connection_pair() {
  printf '%s\n%s' "$DATABASE_URL" "$DATABASE_URL_UNPOOLED" | bun -e '
    const [a,b] = (await Bun.stdin.text()).split("\n").map(value => new URL(value));
    process.exit(a.hostname.replace("-pooler.", ".") === b.hostname
      && a.pathname === b.pathname && a.username === b.username && a.password === b.password
      && a.port === b.port ? 0 : 1);
  '
}

ensure_auth_secret() {
  local current
  current=$(unquote "$(_existing BETTER_AUTH_SECRET || true)")
  if [[ -n "$current" ]]; then
    if [[ ! "$current" =~ ^[A-Za-z0-9_+/=-]{32,}$ ]]; then
      die "The existing auth secret is not a simple 32+ character key. Review it privately; the wizard will not rotate it."
    fi
    write_env BETTER_AUTH_SECRET "$current"
    note "Kept the existing auth secret; no rotation performed."
  else
    current=$(bun -e 'process.stdout.write(require("node:crypto").randomBytes(32).toString("hex"))')
    [[ ${#current} -eq 64 ]] || die "Secret generation failed; nothing was written for this key."
    write_env BETTER_AUTH_SECRET "$current"
    note "Generated a fresh 256-bit secret locally; its value is not displayed."
  fi
}

capture_public_url() {
  local key="$1" kind="$2" candidate
  while :; do
    ask "$key" "Paste the $kind URL:"
    candidate=$(unquote "${!key}")
    candidate=${candidate%/}
    if printf '%s' "$candidate" | bun -e '
      const raw = await Bun.stdin.text();
      try {
        const u = new URL(raw);
        const kind = process.argv[1];
        const clean = !/[\s\x00-\x1f\x7f\x22\x27\x24\x5c]/.test(raw)
          && u.protocol === "https:" && !u.username && !u.password && !u.search && !u.hash;
        const valid = kind === "project"
          ? u.hostname === "vercel.com" && u.pathname.split("/").filter(Boolean).length === 2
          : u.pathname === "/";
        process.exit(clean && valid ? 0 : 1);
      } catch { process.exit(1); }
    ' "$kind"; then
      printf -v "$key" '%s' "$candidate"
      return
    fi
    warn "Use an HTTPS URL without credentials, query parameters, or fragments."
    note "Project: https://vercel.com/your-team/your-project. App: https://your-app.vercel.app."
    confirm "Try entering this URL again?" || die "Stopped. Previously saved values are retained."
  done
}

banner "RescueSync service setup"

stage "Confirm the setup scope"
say "1. Check local prerequisites and file destinations (this stage)."
say "2. Create/reuse a Neon project and a development branch."
say "3. Save DATABASE_URL and DATABASE_URL_UNPOOLED to .env.local (secret)."
say "4. Optionally prepare BETTER_AUTH_SECRET (secret) and BETTER_AUTH_URL (public)."
say "5. Optionally import the published Git repository into Vercel."
say "6. Prepare Production env values in .env.vercel.local and guide a manual Vercel update."
note "Project/app dashboard URLs are used for this run only; the auth app URL is saved if opted in."
note "The script does not push code, migrate a database, create cloud resources via an API, or deploy."
note "Phase 1 remains Demo Mode after setup. No GitHub Actions secrets or provider API tokens are needed."
confirm "Continue with these stages? Optional stages can be skipped" || exit 0
command -v bun >/dev/null 2>&1 || die "Install Bun first: https://bun.sh/docs/installation"
command -v git >/dev/null 2>&1 || die "Install Git before running the setup wizard."
[[ -f package.json && -f drizzle.config.ts ]] || die "This script must live in RescueSync's scripts directory."
[[ "$(git rev-parse --show-toplevel 2>/dev/null)" = "$PROJECT_DIR" ]] || die "Could not confirm the RescueSync repository root."
protect_env_file "$ENV_FILE"
protect_env_file "$DEPLOY_ENV_FILE"
note "Existing keys are preserved unless you deliberately paste a replacement. Files are owner-readable only."
pause

stage "Neon project and development branch"
open_url "https://console.neon.tech/"
step "Sign in and select your organization. Open an existing RescueSync project or choose New Project."
step "For a new project, name it rescuesync and choose a region near your intended Vercel region."
step "Keep the default PostgreSQL version, review the plan, and create the project."
step "Project -> Branches -> New branch. Use your default branch as the parent and name the child development."
step "Choose Schema only for an existing project containing real data; an empty new project can use Current data."
step "Review the branch expiration setting; disable automatic deletion for a long-lived development branch."
step "Click Create. Reuse development on reruns instead of creating duplicates."
note "Keep the default branch separate for future Production credentials."
confirm "Is the development branch ready?" || die "Stopped before capturing credentials. Rerun when ready."

stage "Save local Neon connections"
open_url "https://console.neon.tech/"
step "Open your project -> Connect. Select the development branch, database, and role."
step "Enable Connection pooling. Copy the complete PostgreSQL URL, including its password and SSL options."
capture_connection DATABASE_URL pooled
step "In the same Connect dialog, keep the branch/database/role unchanged and disable Connection pooling."
step "Copy the direct URL. This is used by Drizzle Kit, not by the application runtime."
capture_connection DATABASE_URL_UNPOOLED direct
until check_connection_pair; do
  warn "The pooled and direct URLs must describe the same endpoint, database, role, and password."
  step "Return to Connect, select development, then copy both URLs again."
  confirm "Correct the saved connection pair now?" || die "Stopped. Review the saved pair before running migrations."
  capture_connection DATABASE_URL pooled
  capture_connection DATABASE_URL_UNPOOLED direct
done
note "Saved both local connections. Credentials have not been sent to a remote service by this script."
pause

stage "Optional Better Auth preparation"
say "Better Auth runs inside this Next.js app; it does not require a separate hosted project."
say "This stage prepares future local auth variables only. Authentication is not implemented in Phase 1."
if confirm "Prepare Better Auth variables for Phase 2?"; then
  open_url "https://www.better-auth.com/docs/installation"
  ensure_auth_secret
  CURRENT_AUTH_URL=$(unquote "$(_existing BETTER_AUTH_URL || true)")
  if [[ -z "$CURRENT_AUTH_URL" ]]; then
    write_env BETTER_AUTH_URL "http://localhost:3000"
  else
    note "Kept the existing BETTER_AUTH_URL. Check its port if your local server uses a different one."
  fi
  AUTH_PREPARED=true
  note "No Google OAuth, email provider, or extra project is needed for this preparation."
else
  SKIPPED+=("Better Auth preparation (optional; Phase 1 has demo identities only)")
fi
pause

stage "Optional Vercel project"
if ! git cat-file -e HEAD:package.json 2>/dev/null; then
  warn "The application is not committed yet. Vercel cannot import these local scaffolding files."
  note "Finish the local setup, arrange for the application to be committed and pushed, then rerun this wizard."
  SKIPPED+=("Vercel import: application must be committed and pushed first")
elif confirm "Create/reuse a Vercel project now? Creating a new one includes a hosted demo deployment"; then
  note "Vercel imports the remote Git branch, not uncommitted local changes."
  confirm "Is the intended application branch pushed and ready to publish as a demo?" || die "Stopped before opening deployment setup."
  open_url "https://vercel.com/new"
  step "Sign in, select the intended team, and locate this application's Git repository under Import Git Repository."
  step "Authorize repository access if prompted. Click Import; reuse an existing project instead on reruns."
  step "Project name: rescuesync (or an available name). Framework: Next.js. Root directory: ./"
  step "Build command: bun run build. Install command: bun install --frozen-lockfile. Keep the default output directory."
  step "For a new project, no env variables are required for the Phase 1 demo. Review the settings and click Deploy."
  step "After a successful deployment, open the project overview and copy its dashboard URL from the browser."
  capture_public_url VERCEL_PROJECT_URL project
  step "Open the deployed app and copy its stable Production origin, not a temporary preview or dashboard URL."
  capture_public_url DEPLOYED_APP_URL app
  VERCEL_READY=true
else
  SKIPPED+=("Vercel project and hosting setup (deferred)")
fi
pause

stage "Vercel environment configuration and review"
if [[ "$VERCEL_READY" = true ]] && confirm "Prepare Production env values and add them to Vercel now?"; then
  note "Production uses a separate Neon branch. Preview credentials must never point at Production."
  open_url "https://console.neon.tech/"
  step "Open Connect. Select your default/production branch, database, and role; enable Connection pooling."
  step "Copy its complete pooled URL. It must not be the development connection saved earlier."
  (
    ENV_FILE="$DEPLOY_ENV_FILE"
    capture_connection DATABASE_URL pooled
    if printf '%s\n%s' "$DATABASE_URL" "$(ENV_FILE="$PROJECT_DIR/.env.local" _existing DATABASE_URL)" | bun -e '
      const [a,b] = (await Bun.stdin.text()).split("\n").map(value => new URL(value));
      process.exit(a.hostname === b.hostname ? 0 : 1);
    '; then
      die "The Production endpoint matches development. Use a separate branch and rerun this stage."
    fi
    if [[ "$AUTH_PREPARED" = true ]]; then
      ensure_auth_secret
      write_env BETTER_AUTH_URL "$DEPLOYED_APP_URL"
      if [[ "$(_existing BETTER_AUTH_SECRET)" = "$(ENV_FILE="$PROJECT_DIR/.env.local" _existing BETTER_AUTH_SECRET)" ]]; then
        die "Local and Production auth secrets match. Review them privately; use separate secrets."
      fi
    fi
  )
  DEPLOY_KEYS="DATABASE_URL"
  [[ "$AUTH_PREPARED" = false ]] || DEPLOY_KEYS="$DEPLOY_KEYS BETTER_AUTH_SECRET BETTER_AUTH_URL"
  open_url "$VERCEL_PROJECT_URL/settings/environment-variables"
  step "Open the protected .env.vercel.local file in your editor. Add only these keys in Vercel: $DEPLOY_KEYS"
  step "For DATABASE_URL and BETTER_AUTH_SECRET, select Type: Secret (or Sensitive in older dashboards)."
  step "Select Production only. BETTER_AUTH_URL, when prepared, is a Config value with the deployed app origin."
  step "Save each value. Do not add DATABASE_URL_UNPOOLED to the runtime or upload .env.local to Production."
  note "For Development, use .env.local values. For Preview, use a separate non-production branch and preview-specific auth configuration."
  if confirm "Have you saved and reviewed the listed Production variables?"; then
    if confirm "Proceed with the manual redeployment to apply these environment values?"; then
      open_url "$VERCEL_PROJECT_URL"
      step "Open Deployments, select the intended Production deployment, and use its Redeploy action."
      step "Wait for Ready, then open the app and verify that Demo Mode is still clearly labeled."
      if ! confirm "Did the redeployed app load successfully?"; then
        SKIPPED+=("Vercel redeployment was not confirmed; inspect deployment logs in the dashboard")
      fi
    else
      SKIPPED+=("Redeploy in Vercel to apply newly saved environment values")
    fi
  else
    SKIPPED+=("Add/review Production env variables in Vercel; .env.vercel.local only prepares a local copy")
  fi
else
  SKIPPED+=("Production environment configuration (deferred)")
fi

finish
if [[ -n "$DEPLOY_KEYS" ]]; then note "Production preparation file: $DEPLOY_ENV_FILE ($DEPLOY_KEYS)"; fi
note "Prepared values are not proof that hosted settings were saved; review any remaining items above."
note "Next: bun run dev. For an intentional development-branch migration: bun run db:migrate."
note "No migrations were executed. Better Auth, real data reads, and remote check-in delivery still need Phase 2 implementation."
